render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#vhs-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const vhsStatus = params.vhs_status_text !== undefined ? params.vhs_status_text : 'PLAY  ▶';
const tapeMode = params.tape_mode !== undefined ? params.tape_mode : 'AUTO - CH 03';
const showTimecode = params.show_timecode !== false;
const osdColor = params.osd_color || '#00FF66';
const bgType = params.bg_type !== undefined ? params.bg_type : 1;
const chromaColor = params.chroma_color || '#00FF00';

const rgbShift = params.rgb_shift !== undefined ? params.rgb_shift : 8;
const trackingDist = params.tracking_distortion !== undefined ? params.tracking_distortion : 0.7;
const noiseIntensity = params.noise_intensity !== undefined ? params.noise_intensity : 0.4;
const scanlineAlpha = params.scanline_opacity !== undefined ? params.scanline_opacity : 0.35;
const flickerStr = params.flicker_strength !== undefined ? params.flicker_strength : 0.1;
const vignetteStr = params.curvature_vignette !== undefined ? params.curvature_vignette : 0.7;
const tapeSpeed = params.tape_speed || 1.0;
const fontSize = params.font_size || 26;
const showFrame = params.screen_frame !== false;

const t = time * tapeSpeed;
const flicker = 1 - (Math.random() * flickerStr);

c.save();

if (bgType === 1) {
  c.fillStyle = '#000000';
  c.fillRect(0, 0, width, height);
  const barColors = ['#C0C0C0', '#C0C000', '#00C0C0', '#00C000', '#C000C0', '#C00000', '#0000C0'];
  const barW = width / barColors.length;
  const mainBarH = height * 0.72;
  for (let i = 0; i < barColors.length; i++) {
    c.fillStyle = barColors[i];
    c.fillRect(i * barW, 0, barW + 1, mainBarH);
  }
  const botColors = ['#0000C0', '#131313', '#C000C0', '#131313', '#00C0C0', '#131313', '#C0C0C0'];
  for (let i = 0; i < botColors.length; i++) {
    c.fillStyle = botColors[i];
    c.fillRect(i * barW, mainBarH, barW + 1, height - mainBarH);
  }
} else if (bgType === 2) {
  c.fillStyle = '#0000B2';
  c.fillRect(0, 0, width, height);
} else if (bgType === 3) {
  c.fillStyle = '#101010';
  c.fillRect(0, 0, width, height);
  c.fillStyle = '#FFFFFF';
  const numDots = Math.floor(width * height * 0.08);
  for (let n = 0; n < numDots; n++) {
    const nx = Math.random() * width;
    const ny = Math.random() * height;
    c.globalAlpha = Math.random() * 0.8;
    c.fillRect(nx, ny, 2, 2);
  }
} else if (bgType === 4) {
  c.fillStyle = chromaColor;
  c.fillRect(0, 0, width, height);
}
c.restore();

if (bgType !== 4 && rgbShift > 0) {
  c.save();
  c.globalCompositeOperation = 'screen';
  c.globalAlpha = 0.32;
  c.fillStyle = '#FF0000';
  c.fillRect(-rgbShift, 0, width, height);
  c.fillStyle = '#00FFFF';
  c.fillRect(rgbShift, 0, width, height);
  c.restore();
}

if (bgType !== 4 && trackingDist > 0) {
  c.save();
  const rollY = ((t * 80) % (height + 150)) - 70;
  const rollH = 45 * trackingDist;
  if (rollY > -rollH && rollY < height) {
    const displaceX = (Math.sin(t * 18) * 30 + (Math.random() - 0.5) * 20) * trackingDist;
    try {
      c.drawImage(canvas, 0, Math.max(0, rollY), width, rollH, displaceX, Math.max(0, rollY), width, rollH);
    } catch(e) {}
    c.fillStyle = 'rgba(255, 255, 255, 0.45)';
    for (let l = 0; l < 8; l++) {
      const ly = rollY + Math.random() * rollH;
      if (ly >= 0 && ly <= height) {
        c.fillRect(0, ly, width, 1 + Math.random() * 3);
      }
    }
  }
  c.restore();
}

if (bgType !== 4 && noiseIntensity > 0) {
  c.save();
  c.fillStyle = '#FFFFFF';
  const numDots = Math.floor((width * height * 0.0004) * noiseIntensity);
  for (let n = 0; n < numDots; n++) {
    const nx = Math.random() * width;
    const ny = Math.random() * height;
    const nw = 1 + Math.random() * 3 * noiseIntensity;
    const nh = 1 + Math.random() * 2;
    c.globalAlpha = Math.random() * 0.45 * noiseIntensity;
    c.fillRect(nx, ny, nw, nh);
  }
  c.restore();
}

if (bgType !== 4 && scanlineAlpha > 0) {
  c.save();
  c.fillStyle = '#000000';
  c.globalAlpha = scanlineAlpha;
  for (let y = 0; y < height; y += 3) {
    c.fillRect(0, y, width, 1.2);
  }
  c.restore();
}

if (flickerStr > 0) {
  c.save();
  c.fillStyle = '#000000';
  c.globalAlpha = (1 - flicker) * 0.6;
  c.fillRect(0, 0, width, height);
  c.restore();
}

if (vignetteStr > 0) {
  c.save();
  const grad = c.createRadialGradient(
    width / 2, height / 2, Math.min(width, height) * 0.35,
    width / 2, height / 2, Math.max(width, height) * 0.72
  );
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(0.65, 'rgba(0,0,0,' + (0.35 * vignetteStr) + ')');
  grad.addColorStop(1, 'rgba(0,0,0,' + (0.95 * vignetteStr) + ')');
  c.fillStyle = grad;
  c.fillRect(0, 0, width, height);
  c.restore();
}

if (showFrame) {
  c.save();
  c.strokeStyle = '#120F0D';
  c.lineWidth = Math.min(width, height) * 0.035;
  c.strokeRect(0, 0, width, height);
  c.strokeStyle = '#050505';
  c.lineWidth = Math.min(width, height) * 0.015;
  c.strokeRect(0, 0, width, height);
  c.restore();
}

c.save();
c.fillStyle = osdColor;
c.shadowColor = osdColor;
c.shadowBlur = 8;
c.font = 'bold ' + fontSize + 'px Courier New, Courier, monospace';

const marginX = Math.max(25, width * 0.06);
const marginY = Math.max(30, height * 0.08);

if (vhsStatus.trim().length > 0) {
  c.textAlign = 'left';
  c.textBaseline = 'top';
  c.fillText(vhsStatus, marginX, marginY);
}

if (tapeMode.trim().length > 0) {
  c.textAlign = 'right';
  c.textBaseline = 'top';
  c.fillText(tapeMode, width - marginX, marginY);
}

if (showTimecode) {
  const totalSec = Math.floor(t);
  const hrs = String(Math.floor(totalSec / 3600)).padStart(2, '0');
  const mins = String(Math.floor((totalSec % 3600) / 60)).padStart(2, '0');
  const secs = String(totalSec % 60).padStart(2, '0');
  const timecodeStr = 'SP  ' + hrs + ':' + mins + ':' + secs;
  c.textAlign = 'right';
  c.textBaseline = 'bottom';
  c.fillText(timecodeStr, width - marginX, height - marginY);
}

c.restore();
